style.css:
@-moz-document domain("roblox.com") {
/* ซ่อนค่า Robux เดิม */
  .nav-robux-amount {
    font-size: 0 !important;
  }

  /* แสดง ∞ แทน */
  .nav-robux-amount::before {
    content: "∞";
    font-size: 16px;
    color: #00b06b; /* สีเขียวเหมือน Robux ปกติ */
    font-weight: bold;
  }
}
